var i=`0465-sarma`;var t=`world-0465`;var a=`TR`;var o=`western-asia`;var r=4;var l=86;var s={en:`Sarma`,ua:`Сарма`};var g={en:`A traditional dish from Türkiye, centered on grape leaves, white rice, ground lamb, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: виноградне листя, білий рис, фарш з ягнятини, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var m=[{en:`Separate and blanch the leaves in hot water for about 7 minutes until pliable. Drain and trim thick ribs.`,ua:`Відокремте й бланшуйте листя в гарячій воді приблизно 7 хвилин до гнучкості. Обсушіть і зріжте товсті прожилки.`,t:[`blanching`],m:7,i:[[`grape-leaves`,45,`pcs`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`white-rice`,260,`g`],[`ground-lamb`,200,`g`],[`yellow-onion`,190,`g`],[`parsley`,28,`g`],[`mint`,15,`g`],[`extra-virgin-olive-oil`,30,`ml`]]},{en:`Lay a spoon of rice and lamb filling on each vine leaf, fold in sides and roll firmly but not tightly so the rice can expand.`,ua:`Викладайте ложку рисово-баранячої начинки на кожен виноградний лист, підгортайте боки й згортайте не надто туго, щоб рис міг набухнути.`,t:[`rolling-stuffed-food`],m:17,i:[]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`water`,550,`ml`],[`lemon-juice`,55,`ml`]]}];var d={slug:i,id:t,country:`TR`,region:o,servings:4,minutes:86,title:s,text:g,steps:m};export{a as country,d as default,t as id,l as minutes,o as region,r as servings,i as slug,m as steps,g as text,s as title};